with cleaned as (select *, date_format(opened_date, 'yyyy-MM-dd') as opened_date_label from stores where region is not null) select id, city, region, sqft, max(sqft) over (partition by city, region) as city_max_sqft, lead(sqft, 2) over (partition by city order by opened_date, id) as next_sqft, sum(sqft) over (partition by region order by opened_date, id rows between unbounded preceding and current row) as running_sqft from cleaned
